        internal static extern int flicksnap_window_set_excluded_from_capture(nint handle, byte excluded);

        /// <summary>
        ///  Whether the window has the keyboard right now: `GetForegroundWindow() == hwnd` on Windows (not
        ///  the window's active state, which a `SetForegroundWindow` refused by the foreground lock still
        ///  sets) / `NSApp.isActive &amp;&amp; window.isKeyWindow` on macOS. `out_foreground` is 1 or 0.
        ///
        ///  Status: `FLICKSNAP_OK`; `FLICKSNAP_E_INVALID_ARG` for a zero handle or a null `out_foreground`;
        ///  `FLICKSNAP_E_STATE` off the macOS main thread; `FLICKSNAP_E_UNSUPPORTED` on a platform with neither
        ///  window system.
        ///
        ///  Thread: must be the macOS main thread; any thread elsewhere.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "flicksnap_window_is_foreground", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int flicksnap_window_is_foreground(nint handle, byte* out_foreground);

        /// <summary>
        ///  Brings the window to the front with the keyboard, in one call, and says whether it ended up
        ///  there (`out_in_front`, 1 or 0). Windows: nothing when it already is; then a plain
        ///  `SetForegroundWindow` (allowed after a click on one of our windows); failing that, the
        ///  foreground lock is lifted by making this process the last to send input: Alt down (unless the
        ///  user is physically holding it, part of the hotkey), the unassigned key 0xE8 down and up so the
        ///  Alt reads as part of a chord and no app enters menu mode, `SetForegroundWindow`, Alt up. macOS
        ///  answers `FLICKSNAP_E_UNSUPPORTED` this phase; callers keep their Avalonia activation there.
        ///
        ///  Status: `FLICKSNAP_OK`; `FLICKSNAP_E_INVALID_ARG` for a zero handle or a null `out_in_front`;
        ///  `FLICKSNAP_E_UNSUPPORTED` off Windows.
        ///
        ///  Thread: any thread.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "flicksnap_window_take_foreground", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int flicksnap_window_take_foreground(nint handle, byte* out_in_front);

        /// <summary>
        ///  Moves and resizes the window in one step: `SetWindowPos(x, y, width, height, SWP_NOZORDER |
        ///  SWP_NOACTIVATE | SWP_NOOWNERZORDER)`, `rect` in physical virtual-desktop pixels. Atomic where
        ///  a position set and a size set a layout pass apart would make the window slide and then snap.
        ///  macOS answers `FLICKSNAP_E_UNSUPPORTED` this phase (the caller keeps its toolkit path there).
        ///
        ///  Status: `FLICKSNAP_OK`; `FLICKSNAP_E_INVALID_ARG` for a zero handle, a null `rect` or a negative size;
        ///  `FLICKSNAP_E_OS` when `SetWindowPos` failed; `FLICKSNAP_E_UNSUPPORTED` off Windows.
        ///
        ///  Thread: must be the macOS main thread; any thread elsewhere.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "flicksnap_window_set_bounds", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int flicksnap_window_set_bounds(nint handle, FlickSnapRect* rect);

        /// <summary>
        ///  Windows: calls `callback(user)` whenever the system's foreground window changes, to any window
        ///  of any process, until destroyed (`SetWinEventHook(EVENT_SYSTEM_FOREGROUND)`, out of context, so
        ///  the events arrive through the creating thread's message loop and the callback runs there,
        ///  synchronously, outside any export: it may call exports, README R20). WINEVENTPROC has no user
        ///  parameter, so the crate keeps a hook-to-(callback, user) registry; its lock is released before
        ///  `callback` runs, so destroying the watch from inside the callback cannot deadlock (README C3).
        ///  `*out_watch` is written on `FLICKSNAP_OK` and set to null otherwise.
        ///
        ///  Status: `FLICKSNAP_OK`; `FLICKSNAP_E_INVALID_ARG` for a null `callback` or `out_watch`; `FLICKSNAP_E_OS` when
        ///  `SetWinEventHook` refused; `FLICKSNAP_E_UNSUPPORTED` off Windows.
        ///
        ///  Thread: a thread that pumps window messages; the callback runs on that thread.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "flicksnap_window_foreground_watch_create_windows", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int flicksnap_window_foreground_watch_create_windows(delegate* unmanaged[Cdecl]<void*, void> callback, void* user, FlickSnapForegroundWatch** out_watch);

        /// <summary>
        ///  Windows: ends a foreground watch (`UnhookWinEvent`) and frees it; no callback runs once this
        ///  returns. Must run on the thread that created the watch, since the hook belongs to that thread's
        ///  message loop. A null `watch` is `FLICKSNAP_OK` on every OS. A panic caught in the watch's callback
        ///  path is reported here, after the watch is gone, as `FLICKSNAP_E_PANIC`.
        ///
        ///  Status: `FLICKSNAP_OK`; `FLICKSNAP_E_STATE` on another thread (the watch is left intact);
        ///  `FLICKSNAP_E_PANIC` for a panic recorded by the callback path; `FLICKSNAP_E_UNSUPPORTED` off Windows for
        ///  a non-null `watch`.
        ///
        ///  Thread: a thread that pumps window messages; the callback runs on that thread.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "flicksnap_window_foreground_watch_destroy_windows", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int flicksnap_window_foreground_watch_destroy_windows(FlickSnapForegroundWatch* watch);

        /// <summary>
        ///  macOS: places the close, minimise and zoom buttons at `left_inset` (left edge of the close
        ///  button) and `top_inset` (top edge of all three), in points from the window's top-left, instead
        ///  of the (9, 9) AppKit gives a bare window. The three are translated as a unit, so AppKit's own
        ///  spacing and button size (the small variant under a title bar shorter than 32 pt) are kept, and a
        ///  repeated call computes a zero shift. AppKit resets the frames on every title bar relayout (a
        ///  resize, zoom, minimise and restore, either fullscreen transition), so callers re-apply after
        ///  those. objc2 handles the 32-byte `frame` struct return on both arm64 and x86_64.
        ///
        ///  Status: `FLICKSNAP_OK`; `FLICKSNAP_S_NONE` when the window has no standard buttons or no title bar
        ///  height, so nothing moved; `FLICKSNAP_E_INVALID_ARG` for a zero handle or a non-finite inset;
        ///  `FLICKSNAP_E_STATE` off the main thread; `FLICKSNAP_E_UNSUPPORTED` off macOS.
        ///
        ///  Thread: must be the macOS main thread.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "flicksnap_window_set_traffic_light_position_macos", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int flicksnap_window_set_traffic_light_position_macos(nint nswindow, double left_inset, double top_inset);


